use mill.stock;
use mill.rules;

pub fn lines() -> String {
    var output = "";
    var first = true;

    for plank in stock.inventory() {
        if rules.keep(plank) {
            let label = rules.label(plank);
            if first {
                output = label;
                first = false;
            } else {
                output = output.concat(other: ",").concat(other: label);
            }
        }
    }

    output
}

