use galley.menu::{board};
use galley.kitchen::{serve};

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let dishes = board();
    var first = true;

    for dish in dishes {
        if first {
            first = false;
        } else {
            io.write(text: ";")?;
        }

        serve(io: io, dish: dish)?;
    }

    return Ok(unit);
}

